window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3857052b72ac64de"]={"versions": [{"id": "FIG-3857052b72ac64de", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm bzw. Ablaufdiagramm (Flowchart) zur Spezifikation des Koordinationsalgorithmus für den koordinierten Netzwerk-Shutdown im AUTOSAR-Basissoftwaremodul Network Management Interface (<code>Nm</code>). Das Diagramm beschreibt die algorithmische Kontrollflusslogik beim Übergang mehrerer koordinierter Netzwerkcluster und des lokalen Steuergeräteknotens in den Ruhezustand (Bus-Sleep).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Nm-Koordinator / Nm-Interface</strong>: Zentrale Steuerungslogik des <code>Nm</code>-Moduls zur netzwerkübergreifenden Koordination.\n</li><li><strong>Entitäten</strong>:\n<ul class=\"fig-list\"><li>Lokaler Knoten und zugehörige Netzwerkcluster.\n</li><li>Shutdown-Delay-Timer (ein Timer pro koordiniertem Netzwerkcluster).\n</li><li>Synchronisationsindikationen (NM-Synchronisationsmeldungen über den Bus).\n</li></ul>\n</li><li><strong>Schnittstellen / Aktionen</strong>:\n<ul class=\"fig-list\"><li>Abfrage der Schlafbereitschaft aller Netzwerke und des Knotens.\n</li><li>Empfang der Synchronisationsindikation (optionaler Pfad).\n</li><li>Starten der Shutdown-Delay-Timer.\n</li><li>Shutdown-Befehl für das jeweilige Netzwerk nach Ablauf des spezifischen Timers.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Eintritt über den Initialknoten in die Entscheidung „All networks and node itself ready for sleep?“.\n</li><li><strong>Schlafbereitschaftsprüfung</strong>:\n<ul class=\"fig-list\"><li>Wenn <code>[No]</code>: Schleife zurück zur erneuten Prüfung.\n</li><li>Wenn <code>[Yes]</code>: Übergang zur Synchronisation oder direkt zum Timer-Start.\n</li></ul>\n</li><li><strong>Synchronisation (optional)</strong>:\n<ul class=\"fig-list\"><li>Pfad A: Warten auf eine gültige Synchronisationsindikation („Wait for valid synchronization indication“).\n</li><li>Pfad B: Bypass direkt zum Starten der Shutdown-Delay-Timer.\n</li></ul>\n</li><li><strong>Timer-Initialisierung</strong>: Ausführen von „Start all Shutdown-delay-timers“.\n</li><li><strong>Timer-Ablaufschema</strong>:\n<ul class=\"fig-list\"><li>Eintreten in „Wait for a new timer to expire“.\n</li><li>Sobald ein Timer abläuft: Ausführen von „Command Shutdown for the network with recently expired timer“.\n</li><li>Prüfung „All Timers Expired?“:\n<ul class=\"fig-list\"><li>Wenn <code>[No]</code>: Rückverzweigung zu „Wait for a new timer to expire“.\n</li><li>Wenn <code>[Yes]</code>: Übergang zur finalen Ruhephase.\n</li></ul>\n</li></ul>\n</li><li><strong>Abschluss</strong>: Ausführen von „Wait until all networks are asleep“ und Übergang zum Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert normativ die Ablaufreihenfolge des Koordinationsalgorithmus beim koordinierten Herunterfahren von Netzwerken im <code>Nm</code>. Relevante Aspekte für die Implementierung:</p>\n<ul class=\"fig-list\"><li>Der Algorithmus darf Shutdown-Delay-Timer erst starten, wenn sowohl alle zu koordinierenden Netzwerke als auch die lokale ECU bereit für den Schlafmodus sind.\n</li><li>Die Auswertung der Synchronisationsindikation ist als optionaler Kontrollflusspfad modelliert, der umgangen werden kann.\n</li><li>Das Herunterfahren einzelner Netzwerke erfolgt zeitversetzt und sequentiell basierend auf dem jeweiligen Timer-Ablauf.\n</li><li>Der Gesamtvorgang ist erst abgeschlossen, wenn alle Timer abgelaufen sind und alle beteiligten Busse physisch den Schlafzustand erreicht haben.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0e7dddf000ea3c78", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm bzw. Ablaufdiagramm (Flowchart) zur Spezifikation des Koordinationsalgorithmus für den koordinierten Netzwerk-Shutdown im AUTOSAR-Basissoftwaremodul Network Management Interface (<code>Nm</code>). Das Diagramm beschreibt die algorithmische Kontrollflusslogik beim Übergang mehrerer koordinierter Netzwerkcluster und des lokalen Steuergeräteknotens in den Ruhezustand (Bus-Sleep).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Nm-Koordinator / Nm-Interface</strong>: Zentrale Instanz zur netzwerkübergreifenden Shutdown-Koordination.\n</li><li><strong>Beteiligte Softwareschnittstellen &amp; APIs</strong>:\n<ul class=\"fig-list\"><li><code>BusNm_BusSynchronization</code>: Busspezifische Synchronisations-API (z. B. CanNm/FrNm).\n</li><li><code>BusNm_NetworkRelease</code>: Busspezifische Freigabe des Netzwerks zum Einschlafen.\n</li><li><code>Nm_BusSleepMode</code>: Callback bzw. Benachrichtigung an höhere Schichten über das Erreichen des Bus-Sleep-Modus.\n</li></ul>\n</li><li><strong>Entitäten</strong>:\n<ul class=\"fig-list\"><li>Koordinierte Netzwerke und lokaler Knoten.\n</li><li>Shutdown-Delay-Timer je Netzwerkcluster.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Eintritt über den Start-Pseudozustand in die Entscheidungsraute „all networks and node itself ready for sleep?“.\n</li><li><strong>Schlafbereitschaftsprüfung</strong>:\n<ul class=\"fig-list\"><li>Wenn <code>No</code>: Schleife zurück zur zyklischen Re-Evaluation.\n</li><li>Wenn <code>Yes</code>: Weiterschaltung zu „wait vor valid synchronization indication (optional step)“.\n</li></ul>\n</li><li><strong>Synchronisationsschritt</strong>: Warten auf die Synchronisationsindikation im sequentiellen Ablaufpfad.\n</li><li><strong>Timer-Initialisierung</strong>: Übergang zu „start all shutdown delay timers“.\n</li><li><strong>Timer-Ablaufschema</strong>:\n<ul class=\"fig-list\"><li>Eintritt in „wait for next timer to expire“.\n</li><li>Nach Ablauf eines Timers: Aufruf von <code>BusNm_BusSynchronization</code> gefolgt von <code>BusNm_NetworkRelease</code> für das spezifisch zugeordnete Netzwerk.\n</li><li>Entscheidungsraute „all timers expired?“:\n<ul class=\"fig-list\"><li>Wenn <code>No</code>: Rückführung zu „wait for next timer to expire“.\n</li><li>Wenn <code>Yes</code>: Übergang zu „Wait for all Networks to go to sleep and calling Nm_BusSleepMode“.\n</li></ul>\n</li></ul>\n</li><li><strong>Abschluss</strong>: Warten, bis alle Netzwerke schlafen, gefolgt vom Aufruf von <code>Nm_BusSleepMode</code>, und Übergang in den Endzustand (<code>End</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt normativ die verbindlichen API-Aufrufe während des koordinierten Herunterfahrens fest:</p>\n<ul class=\"fig-list\"><li>Nach Ablauf eines Shutdown-Delay-Timers muss zwingend zuerst <code>BusNm_BusSynchronization</code> und unmittelbar danach <code>BusNm_NetworkRelease</code> des zugehörigen Netzwerks aufgerufen werden.\n</li><li>Ein Bypass-Pfad um den Synchronisationsschritt ist im Kontrollfluss nicht mehr als Verzweigung modelliert; der Schritt ist sequentiell eingeordnet.\n</li><li>Nach Ablauf aller Shutdown-Delay-Timer und dem Einschlafen aller beteiligten Netzwerke ist explizit <code>Nm_BusSleepMode</code> aufzurufen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3857052b72ac64de", "to": "FIG-0e7dddf000ea3c78", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Optionaler Synchronisationsschritt („wait vor valid synchronization indication (optional step)“)</strong>: Der Bypass-Zweig um diesen Schritt entfällt; der Schritt ist nun als fester Knoten im linearen Ablaufpfad integriert (mit redaktionellem Tippfehler „vor“ statt „for“).\n</li><li><strong>Aktion nach Timerablauf</strong>: Ersetzung der generischen Shutdown-Anweisung („Command Shutdown for the network with recently expired timer“) durch die konkreten Funktionsaufrufe <code>BusNm_BusSynchronization</code> gefolgt von <code>BusNm_NetworkRelease</code> für das dem abgelaufenen Timer zugeordnete Netzwerk.\n</li><li><strong>Abschlussaktion</strong>: Ergänzung des Aufrufs von <code>Nm_BusSleepMode</code> im Schritt „Wait for all Networks to go to sleep and calling Nm_BusSleepMode“ (zuvor rein passives „Wait until all networks are asleep“).\n</li><li><strong>Start- und Endknoten</strong>: Beschriftung der UML-Pseudozustände mit „Start“ und „End“.\n</li></ul>"}]};
